function getLocalizedPrayers() {
  const lang = (typeof AppState !== 'undefined' && AppState.language) || 'en';
  if (typeof PRAYERS_I18N !== 'undefined' && PRAYERS_I18N[lang]) return PRAYERS_I18N[lang];
  return (typeof PRAYERS !== 'undefined') ? PRAYERS : {};
}

window.PRAYERS_I18N = PRAYERS_I18N;
window.getLocalizedPrayers = getLocalizedPrayers;
